window.EQ_CRITERIO = [["Selexx (MTA)","Semanal / Mensual / Trimestral / Semestral / Anual","S: limpieza, presiones, fugas, sensores (bitácora MTA-SELEX semanal). M: eléctrico, baleros, bandas, reaprietes (MTA-SELEX mensual). T: paletas y filtros de bombas de vacío. Se: revisión de motor del router y drive. A: servicio general / alineación de ejes.","Operador (diario TPM) + técnico"],["Prensas mecánicas 60 y 90 ton","Semanal / Mensual / Semestral / Anual","S: lubricación, fugas, guardas y paro. M: embrague/freno, baleros, conexiones. Se: ajuste de freno-embrague, baleros de cola. A: revisión estructural y de bancada.","Técnico"],["Prensa fluídica / hidráulicas / dobladoras","Mensual / Trimestral / Anual (+ Semanal en la fluídica)","M: nivel y fugas de aceite, mangueras, tornillería. T: filtros hidráulicos. A: cambio de aceite hidráulico y revisión de bomba.","Técnico"],["Taladros de banco y pedestal, máquinas de soldar","Mensual / Semestral (+ lo capturado)","M: limpieza, cable, interruptor, guardas, banda. Se: baleros, motor, cables de soldar y antorcha.","Técnico"],["Herramienta eléctrica (MTC)","Mensual / Semestral","M: cable, clavija, interruptor, guardas, limpieza de ventilas. Se: carbones, baleros, revisión general.","Técnico / almacén"],["Iluminación (IL)","Trimestral / Anual","T: luminarias fundidas, acrílicos, limpieza. A: medición de niveles de iluminación (NOM-025-STPS).","Técnico"],["Baños","Semanal / Mensual / Semestral","S: fugas, sanitarios, llaves. M: tuberías y drenajes. Se: revisión general y pintura.","Técnico"],["Oficinas y áreas de producción (AG)","Mensual / Semestral / Anual","M: recorrido: contactos, luminarias, puertas, fugas. Se: tableros eléctricos, pintura, señalética. A: mantenimiento mayor del área.","Técnico"],["Site de sistemas","Mensual / Trimestral / Anual","M: temperatura y A.A. T: limpieza, UPS. A: revisión eléctrica y de tierras.","Técnico + Sistemas"],["Cuarto de bombas","Semanal / Mensual / Semestral / Anual","S: presión y fugas. M: arrancadores y tableros. Se: baleros y sellos. A: servicio de bombas.","Técnico"],["Área de gas y vaporizadores / tanques de gas","Semanal / Mensual / Anual","S: fugas (agua jabonosa) y manómetros. M: válvulas y reguladores. A: verificación por unidad autorizada (dictamen).","Técnico + proveedor de gas"],["Pintura (área)","Semanal / Mensual / Semestral / Anual","S: limpieza de cabina y filtros. M: extractores y bandas. Se: horno y quemadores. A: servicio mayor.","Técnico"],["Báscula, área de medidores, estacionamiento","Mensual / Anual","M: inspección visual. A: calibración de báscula, termografía de medidores, pintura de líneas.","Técnico / proveedor"],["Jardín de descanso","Quincenal / Semestral","Q: poda y riego. Se: luminarias, mobiliario.","Servicios generales"],["Compresores (EA)","Semanal / Mensual / Trimestral / Semestral / Anual","S: purga de condensados, nivel de aceite, temperatura (máx. 110 °C), fugas. M: filtro de aire, enfriador. T: filtros (≈1,000 h). Se: aceite (≈4,000 h) y separador. A: servicio mayor del fabricante.","Técnico + proveedor"],["Compresor Bimex (sin uso)","Mensual / Semestral","M: arranque de prueba y fugas. Se: aceite y filtros.","Técnico"],["Secador","Semanal / Mensual / Semestral / Anual","S: purga automática. M: limpieza de condensador. Se: punto de rocío. A: revisión de refrigerante R-410A.","Técnico"],["Extractores de polvo","Semanal / Mensual / Semestral / Anual","S: vaciar contenedores y revisar mangas. M: bandas, motor, ductos. Se: cambio/limpieza de mangas o filtros. A: revisión de ventilador y estructura.","Técnico"],["Vaporizador","Mensual / Semestral / Anual","M: fugas y temperatura. Se: válvulas y controles. A: servicio del proveedor.","Proveedor de gas"],["Inversores fotovoltaicos","Trimestral / Anual","T: alarmas, ventilación, limpieza de paneles. A: apriete de conexiones y termografía.","Técnico eléctrico"],["Máquinas tipo A: Gabbiani, Homag, Enchapadora Blue, láser Gweike, flejadoras, cabina Nordson, drive, CNC Blue, hornos de curado y secado, túnel de lavado, máquina de cajas","Semanal / Mensual / Trimestral / Semestral / Anual","S: limpieza, lubricación, presiones de aire, fugas, sensores y guardas. M: eléctrico, baleros, bandas, cadenas, reaprietes. T: filtros (aire, vacío, láser), boquillas y lentes del láser. Se: revisión de motores, husillos, ópticas y chiller. A: servicio general del fabricante. Láser: revisión diaria en la bitácora del 1er turno.","Operador (TPM) + técnico + proveedor"],["Aires acondicionados (AA)","Mensual / Trimestral / Anual","M: limpieza de filtros, drenaje de condensados, ruido y temperatura de salida. T: lavado de evaporador y condensador, revisión eléctrica y de capacitores, amperaje vs. placa. A: servicio mayor, presiones de refrigerante (R-410A / R-32 / R-22) por técnico certificado.","Técnico + proveedor de refrigeración"],["Patines hidráulicos (EM)","Mensual / Semestral","M: fugas de aceite, ruedas, horquillas, bajada y subida, pasadores. Se: nivel/cambio de aceite hidráulico ISO VG32, purga de aire de la bomba, engrase de ejes.","Técnico"],["Montacargas (EM)","Semanal / Mensual / Trimestral / Semestral / Anual (+ revisión diaria del operador)","D: checklist del operador (frenos, claxon, luces, fugas, llantas). S: niveles (aceite motor, hidráulico AW-46, refrigerante), batería 12 V, cadenas del mástil. M: engrase (grasa de litio grado 3), mangueras, frenos. T: filtros. Se: aceite de motor y transmisión (75W-90). A: servicio mayor del proveedor y revisión de mástil y cadenas.","Operador + técnico + proveedor"],["Tableros eléctricos y transformadores secos (EBT)","Trimestral / Semestral / Anual","T: inspección visual con el tablero cerrado: puertas, rotulado, señalización de riesgo eléctrico, ruido o calentamiento, temperatura del transformador. Se: con LOTO (sin energía y verificado): limpieza interior, reapriete de conexiones, revisión de interruptores y cableado. A: termografía con carga, medición de resistencia de aislamiento y de tierras (NOM-001-SEDE-2012 / NOM-029-STPS).","Técnico eléctrico (con EPP clase dieléctrica)"],["Seguridad: todo mantenimiento con energía eléctrica, aire, gas o partes en movimiento se hace con bloqueo y etiquetado (LOTO) y el EPP correspondiente.","","",""]];
